                            <div style={{fontSize:11,color:C.muted}}>
                              {c.bdn}{(c.razza_calcolata||c.razza)?` · 🧬 ${c.razza_calcolata||c.razza}`:""}
                              {c.nascita&&` · nato ${c.nascita}`}
                            </div>
                          </div>
                          <div style={{textAlign:"right",flexShrink:0}}>
                            {!vivoC&&<Badge label="✝" color={C.morto}/>}
